/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
zones = {'.':(1,'10.14.1.11'), 'com':(2,'10.14.1.12'), 'net':(3,'10.14.1.13'), 'example.com':(4,'10.14.1.14'), 'service.com':(5,'10.14.2.11'), 'lab.net':(6,'10.14.2.12'), 'tools.net':(7,'10.14.2.13'), 'shop.example.com':(8,'10.14.3.11'), 'api.service.com':(9,'10.14.3.12'), 'research.lab.net':(10,'10.14.3.13'), 'ci.tools.net':(11,'10.14.4.11'), 'ai.research.lab.net':(12,'10.14.4.12'), 'data.research.lab.net':(13,'10.14.4.13')}
parents = { 'com':'.','net':'.','example.com':'com','service.com':'com','lab.net':'net','tools.net':'net','shop.example.com':'example.com','api.service.com':'service.com','research.lab.net':'lab.net','ci.tools.net':'tools.net','ai.research.lab.net':'research.lab.net','data.research.lab.net':'research.lab.net'}
conf=Path('lab.conf'); s=conf.read_text()
for i in range(1,15): s=s.replace(f'pc{i}[image]=\"kathara/base\"',f'pc{i}[image]=\"kathara/bind\"')
conf.write_text(s)
for zone,(pc,ip) in zones.items():
    d=Path(f'pc{pc}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
    ns='a.root-servers.' if zone=='.' else f'ns.{zone}.'
    fname='db.root' if zone=='.' else f'db.{zone}'
    (d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion no; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { any; }; };\\n'+f'zone \"{zone}\" {{ type master; file \"/etc/bind/{fname}\"; }};\\n')
    contact='hostmaster.root-servers.' if zone=='.' else f'hostmaster.{zone}.'
    lines=['"'$TTL 3600'"',f'@ IN SOA {ns} {contact} ( 1 3600 900 604800 300 )',f'@ IN NS {ns}',f'{ns} IN A {ip}']
    for child,parent in parents.items():
        if parent==zone:
            childns=f'ns.{child}.'
            lines += [f'{child}. IN NS {childns}', f'{childns} IN A {zones[child][1]}']
    if zone in ('shop.example.com','api.service.com','ci.tools.net','ai.research.lab.net','data.research.lab.net'): lines.append(f'@ IN A {ip}')
    if zone in ('example.com','service.com','lab.net','tools.net'):
        lines += [f'@ IN MX 10 mail.{zone}.',f'mail IN A {ip}']
    if zone=='example.com': lines.append('www IN A 10.14.5.11')
    (d/fname).write_text('\\n'.join(lines)+'\\n')
    with Path(f'pc{pc}.startup').open('a') as f: f.write('\\nsystemctl restart named\\n')
d=Path('pc14/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion yes; allow-recursion { any; }; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { any; }; };\\nzone \".\" { type hint; file \"/etc/bind/db.hints\"; };\\n')
(d/'db.hints').write_text('. 3600000 IN NS a.root-servers.\\na.root-servers. 3600000 IN A 10.14.1.11\\n')
with Path('pc14.startup').open('a') as f: f.write('\\nsystemctl restart named\\n')
for pc in range(16,21):
    with Path(f'pc{pc}.startup').open('a') as f: f.write('\\necho \"nameserver 10.14.4.14\" > /etc/resolv.conf\\n')
PY"

